                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.snitch_final_get_put_away_new AS select _airbyte_data:\"EAN\"::STRING as EAN ,_airbyte_data:\"Name\"::STRING as NAME ,_airbyte_data:\"Type\"::STRING as TYPE ,_airbyte_data:Created::TIMESTAMP as CREATED ,_airbyte_data:Updated::TIMESTAMP as UPDATED ,_airbyte_data:\"Category\"::STRING as \"CATEGORY\" ,_airbyte_data:\"Batch Code\"::STRING as \"Batch Code\" ,_airbyte_data:\"Created By\"::STRING as \"Created By\" ,_airbyte_data:\"Shelf Code\"::STRING as \"Shelf Code\" ,_airbyte_data:\"Putaway Code\"::STRING as \"Putaway Code\" ,_airbyte_data:\"Inventory Type\"::STRING as \"Inventory Type\" ,_airbyte_data:\"Total Quantity\"::INTEGER as \"Total Quantity\" ,_airbyte_data:\"Warehouse Name\"::STRING as \"Warehouse Name\" ,_airbyte_data:\"Putaway Item Id\"::STRING as \"Putaway Item Id\" ,_airbyte_data:\"Item Type skuCode\"::STRING as \"Item Type skuCode\" ,_airbyte_data:\"Putaway qc Comment\"::STRING as \"Putaway qc Comment\" ,_airbyte_data:\"Putaway Status Code\"::STRING as \"Putaway Status Code\" ,_airbyte_data:\"Bad inventory Reason\"::STRING as \"Bad inventory Reason\" ,_airbyte_data:\"Putaway Item Status Code\"::STRING as \"Putaway Item Status Code\" ,_airbyte_data:\"Putaway Completed Quantity\"::INTEGER as \"Putaway Completed Quantity\" from snitch_db.maplemonk._airbyte_raw_snitch_final_get_put_away_new QUALIFY ROW_NUMBER () OVER (PARTITION BY \"Putaway Item Id\",\"Warehouse Name\",\"Putaway Code\",Created ORDER BY _airbyte_data:\"Updated\" DESC ) = 1 ; CREATE OR REPLACE TABLE snitch_db.maplemonk.putaway_tracking AS SELECT a.\"Putaway Code\", CASE when \"Warehouse Name\" like \'%TAURU%\' AND \"Putaway Code\" = \'PT0004\' THEN \'WH_Transfer_Inward\' when \"Warehouse Name\" like \'%TAURU%\' AND lower(a.\"Created By\") like \'%northemp.050%\' THEN \'WH_Transfer_Inward\' when \"Warehouse Name\" like \'%TAURU%\' AND lower(a.type) like \'%grn%\' and a.created::DATE in (\'2025-09-18\',\'2025-09-19\',\'2025-09-20\',\'2025-09-21\',\'2025-09-22\') THEN \'WH_Transfer_Inward\' when \"Warehouse Name\" like \'%TAURU%\' AND lower(a.\"Created By\") like \'%northemp.049%\' THEN \'Store Return Inward\' when \"Warehouse Name\" like \'%WH1%\' and lower(a.type) like \'%grn%\' and created >= \'2025-04-01\' then \'Store Return Inward\' WHEN LOWER(a.\"Created By\") LIKE \'%store%\' THEN \'Store Return Inward\' WHEN LOWER(a.\"Created By\") LIKE \'%return%\' and lower(a.type) like (\'%grn%\')THEN \'WPR Inward\' WHEN LOWER(a.type) LIKE \'%grn%\' and ( lower(a.\"Created By\") like \'%hemant%\' or lower(a.\"Created By\") like \'%adava%\' or lower(a.\"Created By\") like \'%guramm%\' or lower(a.\"Created By\") like \'%divya%\' ) THEN \'New Inward\' WHEN LOWER(a.type) LIKE \'%grn%\' THEN \'New Inward\' WHEN LOWER(a.type) LIKE \'%reverse%\' OR LOWER(a.type) LIKE \'%return%\' THEN \'B2C Return Inward\' WHEN LOWER(a.type) LIKE \'%cancelled%\' OR LOWER(a.type) LIKE \'%picklist%\' THEN \'Putback Activity\' WHEN LOWER(a.type) LIKE \'%shelf%\' THEN \'Audit Activity\' WHEN LOWER(a.type) LIKE \'%gatepass%\' THEN \'Gatepass Activity\' ELSE \'BAU_PT\' END AS final_type, a.type AS putaway_type, a.created::timestamp AS putaway_created, a.updated::timestamp AS putaway_updated, a.updated::date as putaway_completed_date, a.\"Inventory Type\", CAST(a.\"Total Quantity\" AS NUMERIC) AS total_quantity, CAST(a.\"Putaway Completed Quantity\" AS NUMERIC) AS putaway_completed_quantity, CAST(a.\"Total Quantity\" - a.\"Putaway Completed Quantity\" AS NUMERIC) AS pending_qty, a.\"Putaway Status Code\", upper(a.\"Putaway Item Status Code\") as \"Putaway Item Status Code\" , a.\"Bad inventory Reason\", a.\"Warehouse Name\", a.\"Putaway Item Id\", a.\"Item Type skuCode\", a.\"Putaway qc Comment\", a.\"Created By\", a.\"Shelf Code\", c.skugroup, c.\"SKU_CLASS\" AS class, a.Category, a.EAN, a.NAME AS product_name, a.\"Batch Code\" FROM snitch_db.maplemonk.snitch_final_get_put_away_new AS a LEFT JOIN snitch_db.maplemonk.uc_final_item_master AS c ON a.\"Item Type skuCode\" = c.sku WHERE a.updated::date >= \'2024-04-01\' ; CREATE OR REPLACE TABLE snitch_db.maplemonk.gs_floor_pendency1 AS ( SELECT \"WAREHOUSE\", status as reason, \"SAPL-WH1\" as inward_type, \"SAPL-WH2\" as source, store_returns::integer as quantity, SAPL_EMIZA as remark, \"SAPL-SR\" as dummy_1, TO_DATE(\"TOTAL\",\'DD/MM/YYYY\') as ageing_date FROM SNITCH_DB.MAPLEMONK.GS_FLOOR_PENDENCY ); CREATE OR REPLACE TABLE snitch_db.maplemonk.rts_summary_wh AS WITH rts AS ( SELECT TRY_TO_DATE(entry_date, \'DD/MM/YYYY\') AS date, sku AS style, description, repeat, new_style, CAST(REPLACE(online_qty, \',\', \'\') AS INT) as online_qty, vendor, rts_status, TRY_TO_DATE(expected_delivery_date, \'DD/MM/YYYY\') AS expected_delivery_date, warehouse, class, ars, remark, photoshoot_received, qc_status, qc_report, costing, logic_po, pl_and_cm_receving_date, fabric_dc, work_order, mini_marker, invoice FROM snitch_db.maplemonk.gs_onlinegoods_rts ) SELECT rts.*, am.category, am.name as product_name, am.sku_class, md.final_status, case when logic_po is null and (lower(photoshoot_received) not in (\'yes\') or photoshoot_received is null) then \'Shoot + PO Pending\' when logic_po is null then \'PO Pending\' when lower(photoshoot_received) not in (\'yes\') or photoshoot_received is null then \'Shoot Pending\' else null end as RCA, case when rts.style like \'%MP%\' then \'MARKETPLACE\' when repeat = \'YES\' THEN \'REPEAT\' when md.final_status = \'INWARD_NOT_DONE\' then \'CATALOGUED\' when rts.style like \'%4MLX%\' then \'LUXE\' when lower(description) like \'%trouse%\' THEN \'BOTTOMS\' when lower(description) like \'%short%\' THEN \'BOTTOMS\' when lower(description) like \'%deni%\' THEN \'BOTTOMS\' when lower(description) like \'%py%\' THEN \'BOTTOMS\' when lower(description) like \'%jogg%\' THEN \'BOTTOMS\' when lower(description) like \'%chino%\' THEN \'BOTTOMS\' when lower(description) like \'%track%\' THEN \'BOTTOMS\' when lower(description) like \'%pant%\' THEN \'BOTTOMS\' when lower(description) like \'%cargo%\' THEN \'BOTTOMS\' when lower(description) in (\'trousers\',\'short\',\'boxer\',\'denim\',\'pyjama\',\'\') THEN \'BOTTOMS\' when lower(description) like \'%jac%\' THEN \'WINTER\' when lower(description) like \'%sweat%\' THEN \'WINTER\' end as PRIORITY FROM rts LEFT JOIN snitch_db.maplemonk.uc_final_item_master am ON UPPER(rts.style) LIKE CASE WHEN POSITION(\'-\' IN am.skugroup) > 0 AND LEFT(am.skugroup, 2) = \'SH\' THEN UPPER(SPLIT_PART(am.skugroup, \'-\', 1)) || \'%\' WHEN POSITION(\'-\' IN am.skugroup) > 0 THEN UPPER(SPLIT_PART(am.skugroup, \'-\', 1)) || \'-\' || UPPER(SPLIT_PART(am.skugroup, \'-\', 2)) || \'%\' ELSE UPPER(am.skugroup) || \'%\' END LEFT JOIN snitch_db.maplemonk.sku_group_sample_to_live md ON UPPER(rts.style) LIKE CASE WHEN POSITION(\'-\' IN md.sku_group) > 0 AND LEFT(md.sku_group, 2) = \'SH\' THEN UPPER(SPLIT_PART(md.sku_group, \'-\', 1)) || \'%\' WHEN POSITION(\'-\' IN md.sku_group) > 0 THEN UPPER(SPLIT_PART(md.sku_group, \'-\', 1)) || \'-\' || UPPER(SPLIT_PART(md.sku_group, \'-\', 2)) || \'%\' ELSE UPPER(md.sku_group) || \'%\' END where md.final_status not in (\'NO_ISSUES\',\'others\') ; CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.LOW_QTY_BINS AS with data as ( select facility, \"Shelf Code\" as SHELF_CODE, zone, \"Section Code\" as SECTION_CODE, BIN_CATEGORY,ROW_NAME,RACK_NAME,SHELF_NAME,BIN_NAME, sum(total_qty) as TOTAL_QTY from snitch_db.maplemonk.inventory_bin_analysis where \"Section Code\" not in (\'DEF\') AND lower(\"Shelf Code\") not like \'%half%\' AND (\"Shelf Code\") not like \'%R1-%\' AND (\"Shelf Code\") not like \'%R2-%\' AND (\"Shelf Code\") not like \'%R3-%\' AND (\"Shelf Code\") not like \'%R4%\' AND (\"Shelf Code\") not like \'%R5%\' AND (\"Shelf Code\") not like \'%R6%\' AND (\"Shelf Code\") not like \'%R7%\' AND (\"Shelf Code\") not like \'%R8%\'AND (\"Shelf Code\") not like \'%R9%\' group by 1,2,3,4,5,6,7,8,9 ), analysis as ( select *, CASE WHEN TOTAL_QTY is null or total_qty = 0 then \'0\' WHEN TOTAL_QTY = 1 then \'1\' WHEN TOTAL_QTY = 2 then \'2\' WHEN TOTAL_QTY = 3 then \'3\' WHEN TOTAL_QTY = 4 then \'4\' WHEN TOTAL_QTY = 5 then \'5\' WHEN TOTAL_QTY >= 6 and TOTAL_QTY < 11 then \'6-10\' WHEN TOTAL_QTY >= 11 and TOTAL_QTY <= 15 then \'11-15\' WHEN TOTAL_QTY >= 16 and TOTAL_QTY <= 20 then \'16-20\' WHEN TOTAL_QTY >= 21 and TOTAL_QTY <= 25 then \'21-25\' WHEN TOTAL_QTY >= 26 and TOTAL_QTY <= 50 then \'26-50\' WHEN TOTAL_QTY >= 51 then \'51+\' ELSE NULL END AS BRACKET from data ) SELECT * FROM analysis ; select * from snitch_db.maplemonk.uc_new_get_shelf_report where \"Warehouse Name\" like \'%TAURU%\' ; select * from snitch_db.maplemonk.uc_final_item_master",
